{
  "summary": "提出一个可从现有坐标检验的路径级问题：在 R07 中，A、B 的相对距离是否随时间持续变化，且这种变化是否与此前的相对运动有关？这只涉及二维轨迹统计，不等同于鱼的行为阶段、感觉机制或因果互动。",
  "artifacts": [],
  "evidence": [
    {
      "source_id": "F2",
      "detail": "摘要报告一个特定三维动物群体自组织模型中，先前群体结构会影响集体行为转变。它提供模型动机，不是当前数据存在历史依赖的证据。"
    },
    {
      "source_id": "F3",
      "detail": "摘要说明斑马鱼例行转弯运动学可随发育和形态变化；当前材料没有年龄、身体长度或姿态，不能把二维坐标转移解释为转弯运动学。"
    },
    {
      "source_id": "measurements",
      "detail": "13 条记录各含 44999 帧、两个局部追踪标签的二维坐标；无物理标定、帧率、跨记录身份保证或任务标签。"
    },
    {
      "source_id": "sampled_windows",
      "detail": "R07 的 1000–1156 帧抽样窗口显示 A 从约 (373,208) 移至约 (997,928)，B 从约 (98,105) 移至约 (102,61)，中间坐标随帧变化。该窗口只展示每四帧一个样本，不能据此估计完整运动状态或行为。"
    }
  ],
  "claims": [
    {
      "id": "C1",
      "text": "在 R07 所给抽样窗口中，两条局部追踪坐标序列均随帧改变；这是坐标变化的描述，不是对追随、接近或转弯的判定。",
      "kind": "observation",
      "use": "exploratory",
      "consequence": "可以继续定义相对距离和相对运动统计；行为含义仍需独立标签或实验背景。",
      "basis": {
        "source_ids": ["sampled_windows", "measurements"],
        "record_ids": ["R07"]
      },
      "depends_on": []
    },
    {
      "id": "C2",
      "text": "若可用坐标表示的历史结构与后续相对位移存在关系，则在控制当前相对位置和运动后，加入先前相对运动特征的探索性模型可能改善后续位移预测；目前没有该关系已成立的证据。",
      "kind": "hypothesis",
      "use": "exploratory",
      "consequence": "可用按时间先后划分的探索性拟合比较当前状态模型与加入历史特征的模型，但预测改善不能单独证明因果记忆或社会互动。",
      "basis": {
        "source_ids": ["F2", "measurements"],
        "record_ids": ["R07"]
      },
      "depends_on": ["C1"]
    }
  ],
  "observation": "主观测量定义为 R07 中两条局部追踪坐标的相对距离 d(t)=||position_A(t)-position_B(t)||，单位为原生图像坐标单位。另描述相邻帧相对位移 Δr(t)=r(t)-r(t-1)，不将它命名为接近、逃避或追随。",
  "expectation": "探索性预期：若坐标层面的历史依赖可预测后续相对运动，则在控制当前相对位置与位移后，加入此前相对位移的滞后特征可能改善按时间顺序留出的预测表现。该预期不主张数据必然呈现改善。",
  "expectation_basis": "F2 的摘要给出特定三维自组织模型中群体结构历史影响集体行为转变的例子。它仅构成提出历史依赖问题的理论动机；其模型、群体尺度与当前两条二维坐标记录之间的映射未知。",
  "conditions": [
    "先限定为 R07 单条记录内的坐标统计；A/B 是局部追踪标签，不能假定身份始终稳定。",
    "仅使用有限坐标帧；当前位移用一帧差分，历史窗口可操作性定义为前 10 帧的平均相对位移。10 帧是研究者选择的图像帧尺度，不是经验证的生物时间尺度。",
    "不以 tracker_score 作为概率、行为质量或纳入排除阈值；其语义未记录。",
    "按时间顺序以前 70% 帧拟合、后 30% 帧探索评估；重叠滞后窗口和时间相关性意味着评估并非独立样本验证。",
    "不跨记录比较个体，不使用身体尺度或速度的物理单位；空间及时间标定缺失。"
  ],
  "initial_question": "在 R07 中，当前相对位置和相对位移之外，前 10 帧的平均相对位移是否为下一帧相对位移提供探索性预测信息？",
  "question_to_peers": "对只有两条局部追踪坐标、身份稳定性未知的记录，哪种低参数历史基线最适合比较（例如当前相对位置与位移模型，或再加入滞后相对位移），才能避免把预测关联误称为群体记忆或互动机制？",
  "worked_example": {
    "record_id": "R07",
    "window_frames": [1000, 1156],
    "sampling_stride": 4,
    "description": "给定窗口中 A 的坐标从约 (373,208) 到约 (997,928)，B 从约 (98,105) 到约 (102,61)。这些是每四帧抽样坐标，只用于说明相对坐标会变化；未据此计算或声称距离趋势、状态转变或预测效果。",
    "source_id": "sampled_windows"
  },
  "analysis_plan": {
    "kind": "analysis",
    "question": "在 R07 中，当前相对位置与相对位移之外，前 10 帧平均相对位移能否改善下一帧相对位移的探索性预测？",
    "record_id": "R07",
    "variables": [
      {
        "name": "relative_position",
        "expression": "positions[:,0,:]-positions[:,1,:]",
        "meaning": "A 减 B 的二维相对坐标向量",
        "units": "原生图像坐标单位"
      },
      {
        "name": "separation",
        "expression": "norm(relative_position,axis=-1)",
        "meaning": "两标签坐标间欧氏距离",
        "units": "原生图像坐标单位"
      },
      {
        "name": "relative_step",
        "expression": "diff(relative_position,1,axis=0)",
        "meaning": "相邻帧 A 减 B 的相对位移向量",
        "units": "原生图像坐标单位/帧"
      },
      {
        "name": "history_step_mean",
        "expression": "rolling(relative_step,10)",
        "meaning": "截至当前帧的过去 10 个相对位移的逐坐标平均；首 9 行缺失",
        "units": "原生图像坐标单位/帧"
      },
      {
        "name": "target_next_step",
        "expression": "shift(relative_step,-1)",
        "meaning": "下一帧的相对位移向量",
        "units": "原生图像坐标单位/帧"
      }
    ],
    "outputs": [
      {
        "name": "distance_summary",
        "expression": "separation"
      },
      {
        "name": "next_step_prediction",
        "expression": "target_next_step"
      }
    ],
    "groups": [
      {
        "name": "finite_aligned_rows",
        "where": "isfinite(separation)&isfinite(target_next_step[:,0])&isfinite(target_next_step[:,1])&isfinite(history_step_mean[:,0])&isfinite(history_step_mean[:,1])",
        "values": ["separation", "relative_step", "history_step_mean", "target_next_step"]
      }
    ],
    "model": {
      "target": "target_next_step",
      "features": ["relative_position", "relative_step", "history_step_mean"],
      "train_fraction": 0.7
    }
  },
  "learning_request": {
    "needed": true,
    "gap": "需要可核验的非平衡路径记忆、状态依赖与预测性比较基础，尤其是有限时间序列中历史特征对后续转移的操作化，以及这类预测关联的解释边界。",
    "why_now": "F2 只提供特定模型的摘要结论；当前问题要把理论动机转成坐标层面的操作性比较，需补足适用范围与方法依据。",
    "queries": [
      "截至 2009 年，非平衡随机过程中的历史依赖或记忆如何操作化，如何区分状态依赖与路径依赖？",
      "动物群体或成对轨迹的状态转移分析中，如何比较只用当前状态与加入滞后历史变量的预测模型？",
      "时间相关轨迹数据按时间留出评估的限制，以及滞后特征预测改善不能识别因果互动的经典例子或方法文献"
    ],
    "urls": ["https://doi.org/10.1006/jtbi.2002.3065"],
    "source_ids": [],
    "record_ids": ["R07"],
    "operations": []
  },
  "memory_notes": [
    {
      "key": "trajectory_observation_limits",
      "title": "轨迹观测的解释边界",
      "kind": "correction",
      "mastery": "used",
      "understanding": "二维坐标可支持位置、相对距离和位移的操作性描述；单凭这些量不能识别行为阶段、感觉、姿态、意图或因果机制。坐标变化本身不证明某种行为存在或不存在。",
      "conditions": "本例限于 measurements 元数据与 R07 的 1000–1160 抽样窗口；缺少任务、姿态、物理标定、行为标签和身份稳定性信息。",
      "example": "R07 窗口支持陈述 A、B 坐标随帧变化；不能仅由此称为追随、相遇或转弯。",
      "open_questions": [
        "完整轨迹中相对距离及位移统计如何随坐标和质量定义变化？",
        "R07 的 A/B 追踪身份是否稳定未知。",
        "当前材料不能解释坐标变化对应的行为或机制。"
      ],
      "tags": ["trajectory", "measurement limits", "轨迹", "测量边界", "操作性定义"],
      "sources": ["measurements", "sampled_windows"]
    },
    {
      "key": "group_state_history_model",
      "title": "群体状态与历史依赖",
      "kind": "interpretation",
      "mastery": "explained",
      "understanding": "F2 摘要报告特定三维自组织模型中的群体历史效应。把当前记录的滞后轨迹特征用于预测后续坐标转移，是新的探索性检验提议；即使预测改善，也不能单独确立模型中的集体记忆或因果机制。",
      "conditions": "F2 为摘要层证据，适用范围限于其所述模型背景；当前记录物种之外的实验细节、任务与可比状态定义未知。",
      "example": "比较当前相对位置和位移模型与加入过去 10 帧平均相对位移的模型；预测比较不等同于证明互动。",
      "open_questions": [
        "滞后窗口长度对探索性预测比较有何影响？",
        "当前数据是否表现路径依赖未知。",
        "我不能说明 F2 模型如何映射到 R07。"
      ],
      "tags": ["state transition", "collective memory", "状态转变", "路径历史", "预测边界"],
      "sources": ["https://doi.org/10.1006/jtbi.2002.3065", "measurements"]
    }
  ],
  "memory_use": [
    {
      "key": "trajectory_observation_limits",
      "source_task": "fish_001/inquiry_001",
      "used_for": "将坐标观测与行为/机制解释分开，并限制 worked_example 的结论范围。",
      "scope_check": "适用于二维坐标与缺少任务、姿态及标定信息的当前记录。"
    },
    {
      "key": "group_state_history_model",
      "source_task": "fish_001/inquiry_001",
      "used_for": "把 F2 当作提出历史依赖问题的模型动机，而非当前记录的实证结论。",
      "scope_check": "保留 F2 的特定模型范围；滞后预测方案明确标为未检验假设。"
    }
  ],
  "possible_pretraining_familiarity": "可能熟悉随机过程的马尔可夫性、滞后预测与集体行为模型的一般概念；本答复没有把未检索的一般知识当成外部证据。",
  "limitations": [
    "没有独立核实实验任务、场景、采样频率、空间标定或追踪标签语义。",
    "目前只有 R01、R07、R13 的窗口抽样结果；所提全记录分析尚未执行。",
    "仅有二维坐标时，历史预测关联不能区分个体响应、共同环境驱动、追踪误差或真实互动。",
    "rolling 与下一帧目标的对齐需由控制器执行后核验；时间序列重叠会限制简单训练/评估划分的解释。"
  ],
  "next_actions": [
    "获取关于截至 2009 年路径记忆与滞后预测比较的可核验基础资料。",
    "执行 R07 全记录的相对距离、相对位移及历史特征对齐检查。",
    "先比较当前状态基线与加入历史特征的探索性模型，再判断是否值得拓展到其他记录。"
  ],
  "exploration": {
    "missing_external_facts": [
      "R07 的实验任务、环境几何、光照和鱼的年龄/准备条件未知。",
      "追踪标签的质量码语义及身份稳定性未知。",
      "没有独立帧率或空间校准。"
    ],
    "unselected_definitions": [
      "前 10 帧历史窗口是暂定研究者定义；可比较其他窗口长度。",
      "相对位移使用逐帧差分；是否需要对坐标或位移平滑尚未决定。",
      "若身份交换可能存在，当前 A 减 B 向量的连续性需要另行评估。"
    ],
    "interface_gaps": [
      "尚未获得完整记录的计算结果；只有指定抽样窗口。",
      "计划中的滚动均值与 shift 对齐结果尚未由控制器返回。"
    ],
    "next_action": "先请求路径记忆与时间序列比较基础知识，并执行 R07 全记录的操作性坐标分析。",
    "stalled_reason": "目前不阻塞：可以明确问题并给出可执行定义；机制解释受缺失实验事实限制。",
    "understanding_changed": true
  }
}
